const words={
 en:{securePayment:'Secure payment',refundPolicy:'Full refund policy',prepaid:'Flexible prepaid data',connected:'Stay connected throughout',hero:'Travel across {country} with one prepaid eSIM. Use maps, messages and booking apps without changing your physical SIM.',plans:'See available plans',from:'Plans from',instant:'Instant delivery',noRoaming:'No roaming fees',flexible:'Flexible prepaid data',choose:'Choose your {country} eSIM plan',chooseText:'Choose the data allowance and validity period that match your stay in {country}.',data:'Mobile data',days:'days',popular:'Most popular',continue:'Continue to secure payment',final:'Final step',complete:'Complete your order',review:'Review your {country} plan, then enter delivery and payment details.',explained:'eSIM explained',what:'What is a {country} eSIM?',whatText:'A {country} eSIM is a digital SIM providing mobile data without a physical SIM card.',dataText:'Internet access without traditional calls or SMS.',hotspot:'Personal hotspot',hotspotText:'Most plans support hotspot depending on the device and network.',validity:'Validity starts on connection',validityText:'Your plan starts on its first supported network connection.',coverage:'Coverage in {country}',coverageText:'Use the same eSIM throughout covered areas.',partners:'Local network partners',networks:'Mobile networks in {country}',networkText:'Your device automatically selects an available partner network.',everyTrip:'One plan for every trip',who:'Who should choose a {country} eSIM?',whoText:'Ideal for holidays, city breaks, business trips and longer stays.',holiday:'Holidays',holidayText:'Keep maps, messages and bookings available.',city:'City breaks',cityText:'Use transport, taxi and local apps.',business:'Business travel',businessText:'Stay connected for meetings and work.',long:'Longer stays',longText:'Keep one connection while travelling.',ready:'Ready in minutes',install:'How to install your {country} eSIM',installText:'Prepare it before departure and ac